import json,hashlib
p='/workspace/recovery/agent319/artifacts/batch419-428.json';d={'pages':[],'units':[],'boundary_notes':[],'review_notes':[]}
def add(n,ar,ru,complete=True,join=False):
 if not d['pages'] or d['pages'][-1]['printed_page']!=n:d['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=[]))
 pg=d['pages'][-1];sid=f'v4-p{n:03}-{len(pg["paragraphs"])+1:02}'
 pg['paragraphs'].append(dict(id=sid,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=complete))
 if join:
  u=d['units'][-1];u['source_ids'].append(sid);u['printed_pages'].append(n);u['ar']+=' '+ar;u['ru']+=' '+ru
 else:d['units'].append(dict(id=sid+'-ru',source_ids=[sid],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
add(419,'فالعلم اللّدنيّ: ما قام الدليل الصحيح عليه أنّه جاء من عند الله على لسان رسله. وما عداه فلدنّيّ من لدن نفس الإنسان، منه بدأ وإليه يعود. وقد انبثق سدّ العلم اللّدنيّ، ورخص سعره، حتّى ادّعت كلّ طائفة أنّ علمهم لدنّيّ، وصار من تكلّم في حقائق الإيمان والسلوك وباب الأسماء والصفات بما يسنح له ويلقيه شيطانه في قلبه يزعم أنّ علمه لدنّيّ! فملاحدة الاتّحاديّة وزنادقة المنتسبين إلى السلوك يقولون: إنّ علمهم لدنّيّ. وقد صنّف في العلم اللّدنيّ متهوّكو المتكلّمين وزنادقة المتصوّفين وجهلة المتفلسفين، وكلّهم يزعم أنّ علمه لدنّيّ! وصدقوا وكذبوا! فإنّ اللّدنيّ منسوب إلى «لدن» بمعنى عند، فكأنّهم قالوا: العلم العنديّ، ولكنّ الشأن فيمن هذا العلم من عنده ولدنه.','Знание, дарованное от Него, — ладунни — это то, о чём достоверный довод свидетельствует, что оно пришло от Аллаха устами Его посланников. А всё остальное — «ладунни» от самого человека: от него оно началось и к нему возвращается. Но плотину этого знания прорвало, цена его упала, и каждая группа стала утверждать, что её знание — ладунни. Говорящий об истинах веры и духовного пути, об именах и качествах что взбредёт ему в голову и что внушит его шайтан в сердце, стал заявлять, что его знание — ладунни! Безбожные сторонники единения и еретики, относящие себя к духовному пути, говорят, что их знание — ладунни. О нём писали безрассудные мутакаллимы, еретики среди суфиев и невежды из философствующих, и все они заявляют, что их знание — ладунни! Они и правдивы, и лживы! Ведь слово «ладунни» происходит от «ладун», означающего «у», «от». Они словно говорят: «Знание от кого-то». Но всё дело в том, от кого именно это знание.')
add(419,'وقد ذمّ الله تعالى بأبلغ الذمّ من ينسب إليه ما ليس من عنده، كما قال تعالى: {وَيَقُولُونَ هُوَ مِنْ عِنْدِ اللَّهِ وَمَا هُوَ مِنْ عِنْدِ اللَّهِ وَيَقُولُونَ عَلَى اللَّهِ الْكَذِبَ وَهُمْ يَعْلَمُونَ} [آل عمران: 78]. وقال تعالى: {فَوَيْلٌ لِلَّذِينَ يَكْتُبُونَ الْكِتَابَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَذَا مِنْ عِنْدِ اللَّهِ} [البقرة: 79]. وقال تعالى: {وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَى عَلَى اللَّهِ كَذِبًا أَوْ قَالَ أُوحِيَ إِلَيَّ وَلَمْ يُوحَ إِلَيْهِ شَيْءٌ} [الأنعام: 93].','Всевышний Аллах самым суровым образом осудил приписывающего Ему то, что от Него не исходит. Всевышний сказал: {وَيَقُولُونَ هُوَ مِنْ عِنْدِ اللَّهِ وَمَا هُوَ مِنْ عِنْدِ اللَّهِ وَيَقُولُونَ عَلَى اللَّهِ الْكَذِبَ وَهُمْ يَعْلَمُونَ} — «Они говорят: „Это от Аллаха“, — хотя это не от Аллаха, и сознательно возводят на Аллаха ложь» [«Аль Имран», 3:78]. Всевышний сказал: {فَوَيْلٌ لِلَّذِينَ يَكْتُبُونَ الْكِتَابَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَذَا مِنْ عِنْدِ اللَّهِ} — «Горе тем, кто пишет Писание своими руками, а затем говорит: „Это от Аллаха“» [«Аль-Бакара», 2:79]. И Всевышний сказал: {وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَى عَلَى اللَّهِ كَذِبًا أَوْ قَالَ أُوحِيَ إِلَيَّ وَلَمْ يُوحَ إِلَيْهِ شَيْءٌ} — «Кто несправедливее того, кто возвёл на Аллаха ложь или сказал: „Мне было ниспослано откровение“, — хотя ему ничего не было ниспослано?» [«Аль-Анам», 6:93].')
add(419,'فكلّ من قال: إنّ هذا العلم من عند الله وهو كاذب في هذه النسبة، فله نصيب وافر من هذا الذمّ. وهذا في القرآن كثير، يذمّ من أضاف إليه ما لا علم له به، ومن قال عليه ما لا يعلم. ولهذا رتّب سبحانه المحرّمات أربع','Поэтому всякому, кто говорит: «Это знание от Аллаха», — ложно приписывая его Ему, достаётся большая доля этого порицания. Такое часто встречается в Коране: Он порицает того, кто приписывает Ему то, о чём не имеет знания, и говорит о Нём то, чего не знает. Поэтому Он, пречистый, расположил запретное по четырём',False)
add(420,'مراتب، وجعل أشدّها: القول عليه بلا علم، فجعله آخر مراتب المحرّمات التي لا تباح بحال، بل هي محرّمة في كلّ ملّة على لسان كلّ رسول. فالقائل: إنّ هذا علم لدنّيّ، لما لا يعلم أنّه من عند الله ولا قام عليه برهان من الله أنّه من عنده= كاذب مفتر على الله، وهو من أظلم الظالمين وأكذب الكاذبين.','степеням и самым тяжким из них сделал высказывание о Нём без знания, поставив его на последнюю ступень запретов, которые не становятся дозволенными ни при каких обстоятельствах: они запрещены в каждой религии устами каждого посланника. Кто говорит о том, относительно чего не знает, что оно от Аллаха, и относительно чего нет доказательства от Аллаха, что оно от Него: «Это знание ладунни», — тот лжец, возводящий на Аллаха вымысел, один из самых несправедливых и лживых.',False,True)
add(420,'قوله: (وأمّا جمع الوجود، فهو تلاشي نهاية الاتّصال في عين الوجود محقًّا).','Его слова: «Что касается собранности бытия, то это исчезновение предельного соединения в самом бытии с полным стиранием».')
add(420,'(تلاشي نهاية الاتّصال): هو فناء العبد في الشهود. و(نهاية الاتّصال): هو ما ذكره في الدرجة الثالثة من باب الاتّصال أنّه «لا يدرك منه نعت ولا مقدار إلّا اسم معار، ولمح إليه يشار». فحقيقة الجمع في هذه الدرجة: تلاشي ذلك في عين الوجود، أي في حقيقته. ويريد بالوجود: ما أشار إليه في الدرجة الثانية من باب الوجود، وهو قوله: «وجود الحقّ: وجود عين، منقطعًا عن مساغ الإشارة». فتضمحلّ نهاية الاتّصال في هذا الوجود محقًّا، أي ذوبانًا وفناء.','«Исчезновение предельного соединения» — это фана раба в созерцании. «Предельное соединение» — то, о чём он говорил на третьей ступени главы о соединении: «В нём не постигается ни признак, ни мера: лишь заимствованное имя и мимолётный взгляд, на который указывают». Суть собранности на этой ступени — исчезновение этого в самом бытии, то есть в его действительности. Под бытием он понимает то, на что указал на второй ступени главы о бытии: «Бытие Истинного — непосредственное бытие, недоступное указанию». Предельное соединение исчезает в этом бытии, полностью стираясь, то есть растворяясь и уходя в фана.')
add(421,'قوله: (وأمّا جمع العين: فهو تلاشي كلّ ما تقلّه الإشارة في ذات الحقّ حقًّا).','Его слова: «Что касается собранности непосредственного созерцания, то это действительное исчезновение всего, что несёт указание, в Сущности Истинного».')
add(421,'(تقلّه الإشارة)، أي تحمله وتقوم به. والإشارة تارة تكون باليد والرأس فتكون إيماءً، وتارة تكون بالعين فتكون رمزًا، وتارة تكون باللفظ فتسمّى تعريضًا، وتارة تكون بالذهن والعقل. فتضمحلّ كلّ هذه الأنواع وتبطل عند شهود العين في حضرة الجمع، وظهور جلال الذات المقدّسة. والذات هي الحاملة للصفات والأفعال.','«Несёт указание» — то есть несёт его и служит ему опорой. Указание бывает рукой и головой, и тогда это жест; бывает глазом, и тогда это условный знак; бывает словом, и тогда называется намёком; бывает умом и разумом. Все эти виды исчезают и прекращаются при непосредственном созерцании в присутствии собранности и явлении величия святой Сущности. Сущность — носитель качеств и действий.')
add(421,'فعرفت من هذا: أنّه في الدرجة الأولى يغيب عن جميع العلوم المتعلّقة بالأدلّة والشواهد بالعلم اللّدنيّ. وفي الدرجة الثانية يغيب عن اتّصاله وشهود اتّصاله بالوجود، فإنّ الوجود فوق الاتّصال كما تقدّم. وهذا كما يغيب الواجد الذي قد ظفر بموجوده عن شهود وصوله إليه واتّصاله به، فغيبته عين وجوده عن شهود نفسه وصفاتها. وفي الدرجة الثالثة يضمحلّ كلّ ما تحمله الإشارة إلى ذات أو إلى صفة أو حال أو مقام في ذات الحقّ سبحانه، فلا يبقى هناك ما يشار إليه سواه.','Из этого ты узнал, что на первой ступени он перестаёт замечать все знания, связанные с доказательствами и свидетельствами, будучи поглощён знанием ладунни. На второй ступени он перестаёт замечать своё соединение и созерцание этого соединения, будучи поглощён бытием, поскольку бытие выше соединения, как уже говорилось. Так обретший, достигнув Обретённого, перестаёт созерцать своё достижение Его и соединение с Ним: его исчезновение из созерцания самого себя и своих качеств и есть его обретение. На третьей ступени всё, что несёт указание на сущность, качество, состояние или стоянку, исчезает в Сущности Истинного, пречистого, так что там не остаётся никого, на кого указывали бы, кроме Него.')
add(421,'قوله: (والجمع: غاية مقامات السالكين، وهو طرف بحر التوحيد).','Его слова: «Собранность — предел стоянок идущих, и она — край моря единобожия».')
add(421,'وجه ذلك: أنّ السالك ما دام في سلوكه فهو في تفرقة الاستدلال وطلب','Объяснение этого таково: пока идущий находится в пути, он пребывает в раздельности вывода доказательств и поиска',False)
open(p,'w').write(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
add(422,'الشواهد، فإذا وصل إلى مقام المعرفة وصار همّه همًّا واحدًا لله وفي الله وبالله نزل في منزلة الجمع، وشمّر لركوب بحر التوحيد الذي يتلاشى فيه كلّ ما سوى الواحد القهّار. فالجمع عنده نهاية سفر السالكين إلى الله.','свидетельств. Когда же он приходит к стоянке познания и его устремления становятся единым устремлением — ради Аллаха, в Аллахе и благодаря Аллаху, — он вступает в обитель собранности и готовится выйти в море единобожия, где исчезает всё, кроме Единого, Всепокоряющего. Поэтому собранность, по его мнению, — конец путешествия идущих к Аллаху.',False,True)
add(422,'وهذا موضع غير مسلّم له على إطلاقه، وإنّما غاية مقامات السالكين: التوبة التي هي بدايات منازلهم.','С этим нельзя согласиться безоговорочно. В действительности предел стоянок идущих — покаяние, с которого начинаются их обители.')
add(422,'ولعلّ سمعك ينفر من هذا غاية النفور، وتقول: هذا كلام من لم يعرف شيئًا من طريق القوم، ولا نزل في منازل الطريق! ولعمر الله، إنّ كثيرًا من الناس ليوافقك على هذا، ويقول: أين كنّا؟ وأين صرنا؟ نحن قد قطعنا منزلة التوبة وبيننا وبينها مائة مقام، فنرجع من مائة مقام إليها، ونجعلها غاية مقامات السالكين!','Возможно, твой слух до крайности отталкивает это, и ты скажешь: «Так говорит тот, кто ничего не знает о пути этих людей и не останавливался в обителях пути!» Клянусь жизнью Аллаха, многие согласятся с тобой и скажут: «Где мы были и куда пришли! Мы уже прошли обитель покаяния, между нами и ею сотня стоянок; неужели нам возвращаться к ней через сотню стоянок и считать её пределом стоянок идущих?!»')
add(422,'فاسمع الآن وعره، ولا تعجل بالإنكار، ولا تبارز بالردّ، وافتح ذهنك لمعرفة نفسك، وحقوق ربّك، وما ينبغي له منك، وما له من الحقّ عليك؛ ثمّ انسب أعمالك وأحوالك وتلك المنازل التي نزلتها والمقامات التي قمت فيها لله وبالله إلى عظيم جلاله وما يستحقّه وما هو له أهل. فإن رأيتها وافية بذلك مكافئة له فلا حاجة بك حينئذ إلى التوبة، والرجوع إليها وقوع عن المقامات العليّة، وانحطاط من علوّ إلى سفل، ورجوع من غاية إلى بداية. وما أظنّ ذلك بعيدًا من كثير من المنتسبين إلى هذا الشأن','Теперь выслушай и усвой. Не спеши отвергать, не выступай с опровержением; раскрой свой ум для познания самого себя, прав своего Господа, того, что тебе подобает делать для Него и что ты Ему должен. Затем соотнеси свои дела, состояния, обители, в которых ты останавливался, и стоянки, на которых ты пребывал ради Аллаха и благодаря Аллаху, с величием Его славы, с тем, чего Он заслуживает и чего достоин. Если ты увидишь, что они полностью отвечают этому и соответствуют Ему, тогда у тебя нет нужды в покаянии, а возвращение к нему будет падением с высоких стоянок, нисхождением сверху вниз и возвращением от конца к началу. Думаю, это не так уж далеко от многих относящих себя к этому делу,',False)
add(423,'المغرورين بمعارفهم وأحوالهم وإشاراتهم!','обольщённых своими познаниями, состояниями и указаниями!',False,True)
add(423,'وإن رأيت أنّ أضعاف أضعاف ما قمت به من صدق وإخلاص وإنابة وتوكّل وزهد وعبادة لا يفي بأيسر حقّ له عليك، ولا يكافئ نعمة من نعمه عندك، وأنّ ما يستحقّه لجلاله أعظم وأجلّ وأكثر ممّا يقوم به الخلق= فاعلم الآن أنّ التوبة نهاية كلّ عارف وغاية كلّ سالك، وكما أنّها بداية فهي نهاية، والحاجة إليها في النهاية أشدّ من الحاجة إليها في البداية، بل هي في النهاية في محلّ الضرورة.','Но если ты увидишь, что даже многократно умноженные правдивость, искренность, обращение к Нему, упование, отрешённость и поклонение, которые ты проявил, не исполняют и малейшего из Его прав над тобой, не возмещают ни одной из Его милостей к тебе и что то, чего заслуживает Его величие, больше, выше и многочисленнее всего, что совершает творение, — тогда знай: покаяние — предел всякого познающего и цель всякого идущего. Как оно является началом, так оно является и концом, и нужда в нём в конце сильнее, чем в начале; более того, в конце оно совершенно необходимо.')
add(423,'فاسمع الآن ما خاطب الله به رسوله في آخر الأمر وعند النهاية، وكيف كان رسول الله ﷺ في آخر حياته أشدّ ما كان استغفارًا وأكثره:','Теперь послушай, с чем Аллах обратился к Своему Посланнику в конце дела, при его завершении, и как в конце жизни Посланник Аллаха ﷺ просил прощения усерднее и больше всего:')
add(423,'قال الله تعالى: {لَقَدْ تَابَ اللَّهُ عَلَى النَّبِيِّ وَالْمُهَاجِرِينَ وَالْأَنْصَارِ الَّذِينَ اتَّبَعُوهُ فِي سَاعَةِ الْعُسْرَةِ مِنْ بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ إِنَّهُ بِهِمْ رَءُوفٌ رَحِيمٌ} [التوبة: 117]. وهذا أنزله الله سبحانه بعد غزوة تبوك، وهي آخر الغزوات التي غزاها رسول الله ﷺ بنفسه؛ فجعل الله سبحانه التوبة عليهم شكرانًا لما تقدّم من تلك الأعمال وذلك الجهاد.','Всевышний Аллах сказал: {لَقَدْ تَابَ اللَّهُ عَلَى النَّبِيِّ وَالْمُهَاجِرِينَ وَالْأَنْصَارِ الَّذِينَ اتَّبَعُوهُ فِي سَاعَةِ الْعُسْرَةِ مِنْ بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ إِنَّهُ بِهِمْ رَءُوفٌ رَحِيمٌ} — «Аллах принял покаяние Пророка, мухаджиров и ансаров, последовавших за ним в трудный час, после того как сердца некоторых из них едва не уклонились. Затем Он принял их покаяние. Поистине, Он к ним сострадателен, милосерден» [«Ат-Тауба», 9:117]. Аллах, пречистый, ниспослал это после похода на Табук — последнего похода, в котором Посланник Аллаха ﷺ участвовал лично. Аллах, пречистый, сделал принятие их покаяния благодарностью за предшествовавшие дела и борьбу.')
add(423,'وقال تعالى في آخر ما أنزل على رسوله: {إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا فَسَبِّحْ بِحَمْدِ رَبِّكَ','В одном из последних ниспосланных Своему Посланнику откровений Всевышний сказал: {إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا فَسَبِّحْ بِحَمْدِ رَبِّكَ',False)
add(424,'وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا}. وفي «الصحيح» أنّه ﷺ ما صلّى صلاة بعد إذ أنزلت عليه هذه السورة إلّا قال فيها: «سبحانك اللهمّ ربّنا وبحمدك، اللهمّ اغفر لي». وذلك في نهاية أمره صلوات الله وسلامه عليه. ولهذا فهم منها علماء الصحابة كعمر بن الخطّاب وعبد الله بن عبّاس أنّه أجل رسول الله ﷺ أعلمه الله إيّاه. فأمره سبحانه بالاستغفار في نهاية أحواله وآخر أمره أعلى ما كان مقامًا وحالًا.','وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا} — «Когда придут помощь Аллаха и победа и ты увидишь людей, вступающих в религию Аллаха толпами, прославляй Господа твоего хвалой и проси у Него прощения: поистине, Он — Принимающий покаяние». В «Сахихе» сообщается, что после ниспослания этой суры он ﷺ не совершал ни одной молитвы, не сказав в ней: «Пречист Ты, о Аллах, Господь наш, и хвала Тебе! О Аллах, прости меня». Это было в конце его дела — да благословит его Аллах и приветствует. Поэтому учёные сподвижники, такие как Умар ибн аль-Хаттаб и Абдуллах ибн Аббас, поняли из неё, что Аллах сообщил Посланнику ﷺ о приближении его срока. Он, пречистый, повелел ему просить прощения в конце его состояний и при завершении дела, когда его стоянка и состояние были наивысшими.',False,True)
add(424,'وآخر ما سمع من كلامه عند قدومه على ربّه: «اللهمّ اغفر لي، وألحقني بالرفيق الأعلى».','Последними услышанными его словами при его уходе к Господу были: «О Аллах, прости меня и присоедини меня к высочайшему обществу».')
add(424,'وكان ﷺ يختم كلّ عمل صالح بالاستغفار كالوضوء، والصلاة، والحجّ، والجهاد، فإنّه كان إذا فرغ منه وأشرف على المدينة قال: «آيبون، تائبون، لربّنا حامدون».','Он ﷺ завершал просьбой о прощении всякое благое дело: омовение, молитву, хадж и борьбу. Завершив её и приблизившись к Медине, он говорил: «Возвращаемся, каемся, Господа нашего восхваляем».')
add(424,'وشرع أن يختم المجلس بالاستغفار وإن كان مجلس خير وطاعة.','Он установил завершать собрание просьбой о прощении, даже если это было собрание добра и послушания.')
open(p,'w').write(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
